/* ── when a part of the page is on screen ── */
const seen = new Map();
const io = new IntersectionObserver(es=>es.forEach(e=>{ e.target.classList.toggle("on", e.isIntersecting); const f=seen.get(e.target); if(f) f(e.isIntersecting) }),{threshold:.2});
