  const viewIdx=Z.viewAt.map(([vx,vy])=>{ let b=0,bd=Infinity; for(let i=0;i<n;i++){ const dd=(X[i]-vx)**2+(Y[i]-vy)**2; if(dd<bd){bd=dd;b=i} } return b });
  // The switchbacks start at the first tight bend after Canyon Junction; the tunnel where it goes under.
  { const t0=tunnel.indexOf(true); if(t0>0){ viewIdx[3]=t0; let k=viewIdx[1]+120; while(k<t0&&Math.abs(K[k])<1/90) k++; viewIdx[2]=Math.min(k,t0-200) } }
  const LIM=[45,50,35,40,55,65,45];
  const limAt=i=>{ let l=LIM[0]; viewIdx.forEach((v,k)=>{ if(i>=v) l=LIM[k] }); if(S[n-1]-S[i]<320) l=35; return l };
  const placeAt=i=>{ let name=Z.views[0]; viewIdx.forEach((v,k)=>{ if(i>=v) name=Z.views[k] }); return name };
  const lim=X.map((_,i)=>limAt(i));
  // How fast a car takes it: no faster than the bends allow (0.36 g across), around the limit,
  // a few over it on one open stretch past the overlook, speeding up at 0.25 g and braking at up to 0.38 g.
  const mps=0.44704;
  // the open stretch: the straightest kilometre between the overlook and Checkerboard Mesa
  let openA=viewIdx[4], best=Infinity; const span=260;
