  const ns=sec.i.length;
  sec.i.forEach((i,k)=>{ sec.v.push(v[i]/mps); sec.e.push(E[i]); sec.lim.push(lim[i]);
    const a=v[sec.i[Math.min(ns-1,k+1)]]-v[sec.i[Math.max(0,k-1)]]; const wob=.012*Math.sin(k*1.7)+.008*Math.sin(k*4.1);
    sec.lon.push(a/2/9.81+wob); sec.lat.push(Math.abs(v[i]**2*K[i])/9.81+Math.abs(wob)); sec.side.push(Math.sign(K[i])||1) });
  // the phone reads the push once a second; a three-second average, as the app shows it
