  // The road's bed: within ~120 m of the road the ground is eased to the road's own height, so
  // the road never runs into a cliff or floats over a gully. Not over the tunnel.
  const P=[]; for(let i=0;i<N;i++) P.push(toS(ZD.X[i],ZD.Y[i],ZD.E[i]));
  const wmax=new Float32Array(pa.count), tgt=new Float32Array(pa.count), R0=.7, R1=3.0;
  for(let i=0;i<N;i+=3){ if(ZD.tunnel[i]) continue; const p=P[i];
    const ix0=Math.floor((p.x+SW/2-R1)/dx), ix1=Math.ceil((p.x+SW/2+R1)/dx), iz0=Math.floor((p.z+SH/2-R1)/dz), iz1=Math.ceil((p.z+SH/2+R1)/dz);
    for(let iz=Math.max(0,iz0);iz<=Math.min(segY,iz1);iz++) for(let ix=Math.max(0,ix0);ix<=Math.min(segX,ix1);ix++){
      const k=iz*(segX+1)+ix, vx=-SW/2+ix*dx, vz=-SH/2+iz*dz, dd=Math.hypot(vx-p.x,vz-p.z); const w=1-sstep(R0,R1,dd);
      if(w>wmax[k]){ wmax[k]=w; tgt[k]=p.y-.1 } } }
  for(let k=0;k<pa.count;k++) if(wmax[k]>0) pa.setY(k, lerp(pa.getY(k), tgt[k], wmax[k]));
  pg.computeVertexNormals();
