    [.25,.5,.75,1].forEach((ring,k)=>{ x.beginPath(); x.arc(c,c,r*ring,0,7); x.strokeStyle=`rgba(106,112,120,${k===3?.55:.28})`; x.setLineDash(k===3?[]:[2,3]); x.lineWidth=1; x.stroke() }); x.setLineDash([]);
